import {CUPS,cupDefinition,cupRounds,cupComplete,cupUnlocked,CUP_POINTS,cupStandings,retryAvailable} from './championship.js';
const el=(tag,cls,text)=>{const n=document.createElement(tag);n.className=cls||'';if(text!==undefined)n.textContent=text;return n;};
const button=(name,action,cls='')=>{const b=el('button',cls,name);b.onclick=action;return b;};
export function standingsTable(rows){const table=el('table','cup-standings'),header=table.createTHead().insertRow();for(const t of ['POS','DRIVER','PTS','WINS'])header.append(el('th','',t));const body=table.createTBody();for(const row of rows){const tr=body.insertRow();tr.className=row.id==='player'?'cup-you':'';tr.insertCell().textContent=row.position;const name=tr.insertCell(),dot=el('i','driver-dot');dot.style.background=row.color;name.append(dot,document.createTextNode(row.name));tr.insertCell().textContent=row.points;tr.insertCell().textContent=row.wins;}return table;}
export function appendCupResults(body,result){const section=el('section','cup-result-summary');section.append(el('h3','',result.complete?(result.cupName||'CHAMPIONSHIP')+' COMPLETE':(result.cupName||'CHAMPIONSHIP')+' · ROUND '+(result.round+1)+'/'+(result.totalRounds||5)),standingsTable(result.standings));if(result.bonus)section.append(el('p','cup-prize','Final bonus +'+result.bonus+' ◉'+(result.newPaint?' · Champion Gold paint unlocked':'')));body.append(section);}
export function renderChampionship(panel,profile,hooks){
 const {carName,routeName,worldName,stats,appearance,create,launch,close,retire,newCup,choose,selectedCup}=hooks;
 panel.replaceChildren();const cup=profile.championship.active,complete=cupComplete(cup),def=cupDefinition(cup?.cupKey||selectedCup),rounds=cup?cupRounds(cup):def.rounds;
 panel.setAttribute('aria-label',def.name+' championship');const top=el('div','cup-top');top.append(button('← THE GRID',close),el('b','','COASTLINE / CHAMPIONSHIPS'),el('span','','◉ '+profile.wallet));panel.append(top);
 const body=el('div','cup-body'),ladder=el('div','cup-ladder');ladder.setAttribute('aria-label','Championship progression');
 for(const [i,c] of CUPS.entries()){const unlocked=cupUnlocked(profile,c.id),active=c.id===def.id,blocked=!!cup&&!complete&&c.id!==cup.cupKey,card=button('',()=>choose(c.id),'cup-option');card.dataset.cup=c.id;card.disabled=!unlocked||blocked;card.setAttribute('aria-pressed',String(active));card.setAttribute('aria-label',c.name+(unlocked?' · '+c.rounds.length+' races':' · Locked · Podium in '+cupDefinition(c.previous).name));const distances=c.rounds.map(r=>r.raceLength/1000);card.append(el('small','',String(i+1).padStart(2,'0')+' / '+c.tier),el('strong','',c.name),el('span','',c.rounds.length+' races · '+Math.min(...distances)+'–'+Math.max(...distances)+' km'),el('em','',!unlocked?'🔒 Podium in '+cupDefinition(c.previous).name:blocked?'Finish or retire current cup':active&&cup?(complete?'FINISHED':'IN PROGRESS'):'UNLOCKED'));ladder.append(card);}body.append(ladder);
 const total=rounds.reduce((sum,r,i)=>sum+(cup?.results[i]?.distance??(cup?.results[i]?3000:r.raceLength)),0),hero=el('div','cup-hero');hero.append(el('span','cup-eyebrow',complete?'THE SEASON IS SETTLED':cup?'YOUR TITLE FIGHT':'CLIMB THE CHAMPIONSHIP LADDER'),el('h2','',def.name.toUpperCase()),el('p','',rounds.length+' RACES · '+total/1000+' KM · '+def.tier+(cup?' · '+carName(cup.setup.car)+' · Build locked':' · Fixed challenge')));if(cup?.results.some(r=>!r.distance))hero.append(el('p','cup-note','Earlier round results are kept. New entries use the updated distances.'));body.append(hero);
 let draftCar=profile.car;const layout=el('div','cup-layout'),left=el('section'),right=el('section');
 if(!cup){const fields=el('div','cup-setup'),label=el('label','','YOUR CAR'),select=el('select');select.setAttribute('aria-label','Championship car');for(const id of profile.ownedCars){const o=el('option','',carName(id));o.value=id;select.append(o);}select.value=draftCar;select.onchange=()=>{draftCar=select.value;detail.textContent='Build '+stats(draftCar).upgradeCount+'/12 · Rivals match your car';};label.append(select);const detail=el('small','','Build '+stats(draftCar).upgradeCount+'/12 · Rivals match your car');fields.append(label,detail,el('span','cup-fixed-tier',def.tier+' CUP · '+(def.level==='easy'?'Sweeping curves':def.level==='medium'?'Technical curves':'Tight curves · Elite rivals')),el('p','cup-note',ruleText(def.level)),el('p','cup-note',def.id==='masters'?'The final title. Win it to master the championship ladder.':'Finish in the top three to unlock '+CUPS[CUPS.indexOf(def)+1].name+'.'));left.append(fields);}
 else{const rows=cupStandings(cup),you=rows.find(r=>r.id==='player');if(complete){const podium=el('div','cup-podium');for(const index of [1,0,2]){const row=rows[index],step=el('div','cup-podium-step cup-podium-'+row.position);step.style.setProperty('--driver',row.color);step.append(el('span','',row.position===1?'🏆':String(row.position)),el('b','',row.name),el('small','',row.points+' PTS'));podium.append(step);}left.append(podium,el('p','cup-prize','YOU FINISHED '+you.position+'/6 · +'+(profile.championship.records.find(r=>r.id===cup.id)?.bonus||0)+' ◉'));const next=CUPS[CUPS.indexOf(def)+1];if(next)left.append(el('p','cup-note',cupUnlocked(profile,next.id)?'🔓 '+next.name+' unlocked':'Finish in the top three to unlock '+next.name));}
 else{const rival=you.position===1?rows[1]:rows[0],gap=Math.abs(you.points-rival.points),remaining=rounds.length-cup.results.length;left.append(el('p','cup-gap',!cup.results.length?'The grid is ready':(gap===0?'LEVEL ON POINTS WITH '+rival.name.toUpperCase():gap+' POINT'+(gap===1?'':'S')+(you.position===1?' AHEAD':' BEHIND '+rival.name.toUpperCase()))+' · '+remaining+' RACE'+(remaining===1?'':'S')+' LEFT'));}
 left.append(el('h3','','CHAMPIONSHIP STANDINGS'),standingsTable(rows));if(!complete)left.append(el('p','cup-note',ruleText(def.level)+(def.level==='medium'?' · '+(retryAvailable(cup)?'1 retry left':'Retry used'):'')));}
 right.append(el('h3','','RACE CALENDAR'));const schedule=el('div','cup-calendar');for(const [i,r] of rounds.entries()){const item=el('div','cup-round'+(cup?.results.length===i?' cup-next':''));item.dataset.route=r.route;const finish=cup?.results[i]?.entries.findIndex(e=>e.id==='player'),distance=cup?.results[i]?.distance??(cup?.results[i]?3000:r.raceLength);item.append(el('b','',String(i+1).padStart(2,'0')),el('div','',r.name),el('small','',routeName(r.route)+' · '+worldName(r.world)+' · '+distance/1000+' km'),el('span','',finish>=0?'P'+(finish+1):cup?.results.length===i?'NEXT':'↗'));schedule.append(item);}right.append(schedule,el('p','cup-note','Points '+CUP_POINTS.join(' / ')+' · Ties: wins, podiums, total time.'),el('p','cup-note','Preset weather included. Progress saves after every round.'));layout.append(left,right);body.append(layout);
 if(profile.championship.records.length){const cabinet=el('section','cup-cabinet');cabinet.append(el('h3','','TROPHY CABINET'));for(const c of CUPS){const entries=profile.championship.records.filter(r=>(r.cupKey||'coastline')===c.id);if(!entries.length)continue;const best=Math.min(...entries.map(r=>r.place));cabinet.append(el('span','',(best===1?'🏆':best<=3?'◈':'⚑')+' '+c.name.toUpperCase()+' · BEST P'+best+' · '+entries.length+' FINISH'+(entries.length===1?'':'ES')));}body.append(cabinet);}panel.append(body);
 const actions=el('div','cup-actions');if(!cup)actions.append(el('small','','Race rewards + final bonus · First title unlocks Champion Gold paint'),button('ENTER '+def.tier+' CUP ↗',()=>create({mode:'race',density:'normal',car:draftCar,world:'coast',route:'coast',level:def.level,spec:stats(draftCar),appearance:appearance(draftCar)},def.id),'cup-primary'));
 else if(complete)actions.append(el('small','','Championship saved · Champion Gold: '+(profile.cosmeticUnlocks.includes('champion')?'UNLOCKED':'Win a title')),button('CHOOSE NEXT CUP ↗',newCup,'cup-primary'));
 else actions.append(button('Retire cup',()=>{actions.replaceChildren(el('span','','Retire this cup? Earned coins are kept.'),button('Keep racing',()=>renderChampionship(panel,profile,hooks)),button('Retire',retire));}),button(cup.inProgress?'CONTINUE ROUND '+(cup.results.length+1)+' ↗':'RACE '+(cup.results.length+1)+' / '+rounds.length+' ↗',()=>launch(cup),'cup-primary'));panel.append(actions);
}
function ruleText(level){return level==='easy'?'Unlimited in-round restarts. Finished rounds are sealed.':level==='medium'?'One restart per cup. Finished rounds are sealed.':'No in-round restarts. Interrupted rounds can restart.';}
